INSERT INTO coaching_formate
  (coach_benutzer_id, titel, kategorie, kurzbeschreibung, ziel, ablauf, dauer_minuten, materialien, hinweise, quellen, tags, freigabe)
VALUES
(@format_owner_id,'1-2-3 Meta','Kommunikation','Perspektivwechsel bei Konflikten mit mehreren Beteiligten.','Konflikt oder Gespräch aus mehreren Perspektiven betrachten und Ressourcen sowie Erkenntnisse herausarbeiten.','Klient wählt Thema. Coach führt nacheinander in die eigene Position, die Position der anderen Person und eine Expertenposition. In Meta-Position Erkenntnisse sammeln und Ressourcen in die beteiligten Positionen geben. Durchläufe bis zur Klärung; anschließend Future Pace für die nächste Begegnung.',NULL,'Bodenanker für Positionen','Quelle beschreibt Coachingablauf; Ergebnisse nicht als Tatsachen über andere Personen behandeln.','https://www.nlphamburg.de','Konflikt,Perspektivwechsel','privat'),
(@format_owner_id,'Angstgegner','Submodalitäten','Bei Unwohlsein gegenüber einer Person laut Präsentation.','Innere Repräsentation und begleitendes Gefühl untersuchen und verändern.','Person innerlich vorstellen und visuelle, auditive und kinästhetische Eigenschaften erfragen. Darstellung im inneren Bild verkleinern, entfernen, unschärfer oder leiser machen. Zwischen Wiederholungen Augen öffnen; Ablauf mehrfach wiederholen und anschließend zukünftige Begegnung vorstellen.',NULL,'','Ungeprüfter Präsentationsinhalt. Nicht als Behandlung einer Angststörung verwenden; bei starkem Leidensdruck qualifizierte Hilfe hinzuziehen.','https://www.nlphamburg.de','Submodalitäten,Angst','privat'),
(@format_owner_id,'Anker verschmelzen','Ankern','Wenn ein negatives Gefühl mit einem gewünschten Zustand verbunden werden soll.','Ressourcen neben einer belastenden Reaktion verfügbar machen.','Rapport herstellen, negativen Anker setzen und Gefühl skalieren. Separator. Positiven Anker für gewünschtes Gefühl setzen. Beide Anker nacheinander auslösen, positiven verstärken und negativen langsam lösen. Future Pace und Skalierung.',NULL,'','Die Folie enthält eine Kurzbeschreibung; Ablauf vor praktischer Nutzung fachlich prüfen.','https://www.nlphamburg.de','Ankern,Ressourcen','privat'),
(@format_owner_id,'AZH – Augen-Zugangs-Hinweise','Wahrnehmung','Die Präsentation nennt alte Themen und Erlebnisse als Anwendungsbereich.','Wahrnehmungen und Reaktionen zu einer gewählten Situation erkunden.','Augenbewegungsradius testen. Klient durch sechs Positionen führen (Ve, VK, A°, Ak, AiD, K+/-). Eine Situation wählen und an jeder Position fragen, was erlebt wird, wie es geht, was stört und wie es stattdessen sein soll.',NULL,'Stift als Orientierungshilfe','Ungeprüfter Präsentationsinhalt. Die Folie erwähnt Traumata. Nicht als Traumabehandlung verstehen; bei Traumafolgen an qualifizierte Fachstellen verweisen.','https://www.nlphamburg.de','Wahrnehmung,Reflexion','privat'),
(@format_owner_id,'Core-Transformation','Innere Anteile','Bei unerwünschten Reaktionen und Verhaltensweisen laut Präsentation.','Positive Absicht eines inneren Anteils erkunden und gewünschte Kernzustände identifizieren.','Teil und Ausgangssituation bestimmen. Positive Absicht erfragen und Ergebniskette bis zu einem erfüllten Kernzustand erkunden. Kernzustand erleben und auf frühere Stationen beziehen. In Teil 2 aus der Startsituation heraustreten, Anteil mit Ressourcen versorgen, integrieren und Zukunft/Gegenwart auf der Timeline betrachten.',NULL,'Bodenanker optional','Komplexer, ungeprüfter Präsentationsinhalt. Nicht für Selbstbehandlung von Trauma, Schmerzen oder selbstschädigendem Verhalten gedacht; nur innerhalb eigener Qualifikation und mit Einwilligung einsetzen.','https://www.nlphamburg.de','Innere-Anteile,Ressourcen','privat'),
(@format_owner_id,'Diamond','Entscheidungen','Innere Konflikte, Dilemmata und Suche nach neuen Blickwinkeln.','Wichtige Aspekte von Problem, Alternative, beidem und weiteren Möglichkeiten erkunden.','Vier Positionen auslegen: Problem, Alternative, beides und weder noch. Jede Position in VAKOG erleben und danach fragen, was ermöglicht oder verhindert wird und was wichtig ist. Aus der Mitte heraus reflektieren.',NULL,'Vier Bodenanker','Ablauf aus Präsentation zusammengefasst.','https://www.nlphamburg.de','Entscheidung,Dilemma','privat'),
(@format_owner_id,'Dickens Pattern','Glaubenssätze','Bei einschränkenden Glaubenssätzen laut Präsentation.','Mögliche Folgen eines Glaubenssatzes über Zeiträume reflektieren.','Einen einschränkenden Glaubenssatz auswählen. Nachteile in Vergangenheit und Gegenwart erkunden und mögliche Folgen für die Zukunft reflektieren.',NULL,'Timeline optional','Die Folie weist selbst auf mögliche Problemverstärkung hin. Belastung beobachten und bei Überforderung abbrechen.','https://www.nlphamburg.de','Glaubenssätze,Timeline','privat'),
(@format_owner_id,'Entscheidungsspinne der Zukunft','Entscheidungen','Bei mehreren Optionen, Zielkonflikten oder Unsicherheit über den passenden Weg.','Zukünftige Optionen vergleichbar machen und Ressourcen sowie Wegpunkte erkunden.','Ziele und Zeitpunkte auswählen. Für jede Option ein dissoziiertes Zielbild auf der Zukunfts-Timeline platzieren. Wege durchlaufen und erleben; Ressourcen, Erfahrungen und Werte ergänzen. Zwischen Timeline und Meta-Position wechseln, Optionen prüfen und am Entscheidungspunkt entscheiden. Future Pace.',NULL,'Bodenanker für Zeitlinien','Ablauf aus Präsentation zusammengefasst; keine Entscheidung für den Klienten vorgeben.','https://www.nlphamburg.de','Zukunft,Entscheidung','privat'),
(@format_owner_id,'Fast Phobia Cure','Submodalitäten','Die Präsentation beschreibt Varianten mit doppelter Dissoziation und schnellem Rücklauf.','Eine angstauslösende innere Vorstellung bearbeiten und gewünschte Ressourcen erproben.','Gewünschten Zustand und Ökologie besprechen; Ressourcenanker aufbauen. Kinofilm-Situation mit sicherer Distanz vorstellen, schwarz-weißen Film vom sicheren Anfang bis kurz vor den Höhepunkt abspielen, dann assoziiert in ein Standbild gehen und den Film schnell rückwärts laufen lassen. Mehrfach wiederholen; Reaktion prüfen und Zukunftssituation vorsichtig vorstellen.',NULL,'','Ungeprüfter Inhalt zu Phobien. Nicht als Therapieanleitung verwenden. Bei Phobien/Traumafolgen nur durch entsprechend qualifizierte Fachpersonen; jederzeit stoppen, Einwilligung und Belastbarkeit beachten.','https://www.nlphamburg.de','Angst,Submodalitäten','privat'),
(@format_owner_id,'Future Pace','Transfer','Am Ende eines Formats laut Präsentation.','Erworbene Ressourcen oder neue Handlungsweisen auf eine künftige Situation beziehen.','Eine zukünftige Situation vorstellen lassen und in VAKOG erkunden. Gefühl skalieren, gewünschte Veränderung wahrnehmen und prüfen, was anders ist.',NULL,'','Kurzformat; je nach Kontext mit Einwilligung und ohne Ergebnisversprechen.','https://www.nlphamburg.de','Transfer,Zukunft','privat'),
(@format_owner_id,'Glaubenssatz auf Timeline','Glaubenssätze','Bei bekannten einschränkenden Glaubenssätzen.','Gewünschten Glaubenssatz und erforderliche Wegpunkte/Ressourcen erkunden.','Timeline mit Gegenwart und Zukunft auslegen. Gewünschten Glaubenssatz dissoziiert in der Zukunft platzieren. Assoziiert von der Gegenwart dorthin gehen. In Meta-Position Ressourcen, Erfahrungen und Schritte ergänzen. Zwischen den Positionen wechseln, bis es stimmig wirkt; Zielzustand ankern.',NULL,'Bodenanker','Die Präsentation verbindet dies mit „Verlockende Zukunft“; siehe separaten Eintrag.','https://www.nlphamburg.de','Glaubenssätze,Timeline','privat'),
(@format_owner_id,'Magic Mirror','Selbstbild','Bei Unzufriedenheit im Lebensbereich laut Präsentation.','Selbstbild und gewünschte Veränderung über Lebensbereiche reflektieren.','Lebensbereich wählen und Dilts-Ebenen mit Bodenankern erkunden. Auf jeder Ebene hilfreiche und hinderliche Aspekte betrachten. Ein wertschätzendes Wesen und einen Spiegel als Vorstellungsbilder nutzen, ein gewünschtes Selbstbild erkunden und Ebenen erneut durchgehen. Entscheidung und Zukunftsbezug prüfen.',NULL,'Bodenanker','Ungeprüfter Präsentationsinhalt; keine Wirkung oder Veränderung garantieren.','https://www.nlphamburg.de','Selbstbild,Dilts','privat'),
(@format_owner_id,'Mentoren-Technik','Ressourcen','Bei festgefahrenen Situationen, Veränderungswunsch oder Ideenfindung.','Perspektiven und Ressourcen fiktiver oder realer Mentoren erkunden.','Ausgangssituation und Gefühl skalieren. Meta- und Ressourcenplatz bestimmen. Einen bis drei Mentoren auswählen und Rat/Ressourcen in die Situation geben lassen. Erkenntnisse sammeln, Ressourcen annehmen und Situation mit den Ressourcen erneut vorstellen. Future Pace und Skalierung.',NULL,'Bodenanker optional','Mentoren können fiktiv oder real sein; Ratsuchenden eigene Entscheidungshoheit lassen.','https://www.nlphamburg.de','Mentoren,Ressourcen','privat'),
(@format_owner_id,'Neurologische Uhr der Zukunft','Ziele und Sinn','Fragen nach Aufgabe, Sinn und gewünschter Wirkung im Leben.','Langfristige Perspektiven und nächste Schritte reflektieren.','Zeitpositionen für Gegenwart, zwei bis drei Jahre, etwa fünfzehn Jahre und Lebensabend auslegen. Mission/Absicht und relevante Ebenen an jeder Position erkunden. In Meta-Position Erkenntnisse, Beschreibung und mögliche Schritte schriftlich festhalten.',NULL,'Bodenanker / Zeitlinie','Zeitpunkte gemäß Präsentation; an Lebenssituation der Person anpassen.','https://www.nlphamburg.de','Sinn,Zukunft','privat'),
(@format_owner_id,'New Behaviour Generator','Verhalten','Neues Verhalten einüben oder ein Modell beobachten.','Gewünschtes Verhalten gedanklich erproben und auf Passung prüfen.','Echtes oder fiktives Modell wählen und gewünschtes Verhalten bestimmen. Modell aus verschiedenen Perspektiven beobachten. Eigenes Selbstbild zunächst dissoziiert mit dem Verhalten vorstellen, dann assoziiert erproben. Änderungen prüfen, Öko-Check, Integration und Future Pace.',NULL,'','Das ist eine Übungsbeschreibung, kein Ersatz für reale Übung oder fachliche Beratung.','https://www.nlphamburg.de','Verhalten,Modelllernen','privat'),
(@format_owner_id,'Parts Party / Systemische Aufstellung','Innere Anteile','Sichtbarmachung von Problemstrukturen und Wechselwirkungen laut Präsentation.','Unterschiedliche Perspektiven/Anteile und mögliche Kooperation explorieren.','Gastgeber benennt Anteile und erstellt Karten mit Attributen, Absicht und Verhalten. Stellvertretende wählen, Rollen einnehmen und im Raum aufstellen. Coach begleitet Interaktion, Reflexion, Konflikt und mögliche Kooperation. Abschluss mit Ressourcen, Akzeptanz und Entlassen der Stellvertretenden.',NULL,'4–8 Stellvertretende; Rollenkarten','Komplexes Gruppenformat. Präsentation empfiehlt eine begleitende Person, die den Zustand des Klienten im Blick behält. Belastung beobachten und jederzeit stoppen.','https://www.nlphamburg.de','Systemisch,Innere-Anteile','privat'),
(@format_owner_id,'Pimp up myself','Selbstwert','Selbstwert, Selbstkenntnis und Klarheit laut Präsentation.','Verschiedene Selbstbilder und gewünschte Ressourcen wahrnehmen.','Bodenanker für Selbstbild und Meta-Position installieren. Verschiedene Selbstbilder mit Attributen und Submodalitäten erkunden; zwischendurch aus Meta reflektieren. Ein Fülle-Selbst beschreiben, erleben und ankern. Präsentation enthält eine Checkliste innerer und äußerer Submodalitäten.',NULL,'Bodenanker','Ungeprüfter Präsentationsinhalt; sensible Selbstwertthemen achtsam begleiten.','https://www.nlphamburg.de','Selbstwert,Selbstbild','privat'),
(@format_owner_id,'Problemgenerator','Reflexion','Struktur eines Problems und mögliche Dilts-Ebenen untersuchen.','Problemkontext, Gedanken und mögliche positive Absicht strukturiert erkunden.','Beispiele lesen, Resonanzen notieren und einen Fokus wählen. Situation in VAKOG beschreiben, auf Dilts-Ebenen betrachten, kritischen Punkt und Skalierung erfragen, mögliche positive Absicht erkunden und Problem/Glaubenssatz beschreiben.',NULL,'','Die Folie enthält Fragen zu Sucht, Essstörungen, Missbrauch, emotionalen und körperlichen Beschwerden. Diese Fragen sind keine Diagnostik. Bei entsprechenden Hinweisen nicht weiter explorieren, sondern qualifizierte Unterstützung empfehlen.','https://www.nlphamburg.de','Reflexion,Dilts','privat'),
(@format_owner_id,'Six-Step-Reframing','Innere Anteile','Unerwünschtes Muster oder Veränderungswunsch laut Präsentation.','Positive Absicht eines Anteils und alternative Verhaltensweisen erkunden.','Muster und Auslöser in VAKOG bestimmen. Zugehörigen Anteil als innere Vorstellung erkunden. Verhalten und Absicht unterscheiden, positive Absicht erfragen und mehrere neue Verhaltensmöglichkeiten entwickeln. Passende Möglichkeit auswählen, integrieren, Öko-Check und Future Pace.',NULL,'','Bei psychosomatischen Symptomen oder starker Belastung nicht als Behandlung verwenden; Präsentationsinhalt ist nicht unabhängig geprüft.','https://www.nlphamburg.de','Reframing,Innere-Anteile','privat'),
(@format_owner_id,'Swish','Verhalten','Unerwünschtes Verhalten oder eine unerwünschte Reaktion laut Präsentation.','Auslösendes inneres Bild mit einem attraktiven Zielbild verknüpfen.','Auslösendes assoziiertes Bild und attraktives dissoziiertes Zielbild bestimmen. Ausgangsbild groß/hell, Zielbild klein/dunkel platzieren. Beide in der beschriebenen gegenläufigen Bewegung tauschen; Augen öffnen als Separator. Mehrfach schneller wiederholen und testen.',NULL,'','Ungeprüfter Präsentationsinhalt; nicht als Therapie für psychische Erkrankungen verstehen.','https://www.nlphamburg.de','Verhalten,Submodalitäten','privat'),
(@format_owner_id,'Teile verhandeln','Innere Anteile','Bei inneren Konflikten und widersprüchlichen Impulsen.','Absichten beteiligter Anteile erkunden und mögliche gemeinsame Handlungsoptionen finden.','Muster und beteiligte Teile in VAKOG bestimmen. Teile getrennt beschreiben, Verhalten und Absicht unterscheiden, positive Absichten erkunden. Gemeinsame höhere Absicht suchen, neue Verhaltensoptionen verhandeln, integrieren, Öko-Check und Future Pace.',NULL,'','Bei starken inneren Konflikten oder psychischen Beschwerden qualifizierte Unterstützung hinzuziehen; Inhalt nicht unabhängig geprüft.','https://www.nlphamburg.de','Reframing,Innere-Anteile','privat'),
(@format_owner_id,'Timeline / Change History','Timeline','Die Präsentation nennt festgefahrene Situationen, fehlende Ressourcen und einschränkende Überzeugungen.','Vergangene Lernerfahrungen und hilfreiche Ressourcen reflektieren.','Timeline auslegen und Gegenwartssituation in VAKOG erkunden. Gefühl und Suchanker bestimmen und mit diesem in frühere Situationen gehen. Einen prägenden Zeitpunkt identifizieren, benötigte Ressourcen erfragen und diese in Imprint, Timeline, Gegenwart und Zukunft einbringen. Zur Gegenwart zurückkehren und Future Pace.',NULL,'Bodenanker / Zeitlinie','Die Präsentation erwähnt Depressionen, Trauma und Angst. Kein Ersatz für psychotherapeutische oder medizinische Behandlung; bei Traumafolgen nur fachlich qualifiziert begleiten.','https://www.nlphamburg.de','Timeline,Ressourcen','privat'),
(@format_owner_id,'Timeline Re-Imprint','Timeline','Die Präsentation beschreibt eine Variante mit beteiligten Personen.','Ressourcen und alternative Reaktionen in eine erinnerte Situation einbringen.','Ausgangssituation und Timeline bestimmen. Mit Suchanker einen früheren Zeitpunkt erkunden. Ressourcen in die Timeline geben; beteiligte Personen identifizieren und deren Perspektiven in der Vorstellung berücksichtigen. Situation mit neuen Ressourcen erneut erleben und Zukunftsbezug nur mit Zustimmung des Klienten erkunden.',NULL,'Bodenanker / Zeitlinie','Ungeprüfter Inhalt zu Erinnerungen und belastenden Situationen. Nicht als Traumabehandlung verwenden; bei Belastung sofort stoppen und qualifizierte Hilfe hinzuziehen.','https://www.nlphamburg.de','Timeline,Ressourcen','privat'),
(@format_owner_id,'Verlockende Zukunft','Ziele und Zukunft','Ziele finden, Zukunft planen und Ressourcen klären laut Präsentation.','Zielbild, Wegpunkte und benötigte Ressourcen prüfen.','Ziel wählen und dissoziiertes Zielbild auf einer Zukunfts-Timeline platzieren. Zeitpunkte festlegen und den Weg wiederholt erkunden. Aus Meta Wegpunkte, Schritte, Ressourcen, Erfahrungen und Werte ergänzen. Zwischen Timeline und Meta wechseln, bis Ziel und Weg geklärt wirken. Future Pace und gewünschtes Gefühl wahrnehmen.',NULL,'Bodenanker / Zeitlinie','Verwandte Variante „Glaubenssatz auf Timeline“ ist separat dokumentiert.','https://www.nlphamburg.de','Ziele,Timeline','privat'),
(@format_owner_id,'Walt Disney','Kreativität','Wenn Ziele noch unklar sind oder genauer ausgearbeitet werden sollen.','Ideen aus drei Perspektiven entwickeln und prüfen.','Bodenanker für Träumer, Kritiker und Planer auslegen und jeweils in VAKOG erkunden. Zwischen den Positionen wechseln, bis die Idee stimmig und umsetzbar erscheint. Im Planer enden und Ziel schriftlich festhalten.',NULL,'Drei Bodenanker','Ablauf gemäß Präsentation zusammengefasst.','https://www.nlphamburg.de','Kreativität,Ziele','privat'),
(@format_owner_id,'Wohlgeformte Ziele','Ziele','Wenn ein Ziel klar ist und der Weg geprüft werden soll.','Ein konkretes, eigenständig erreichbares und ökologisch geprüftes Ziel formulieren.','Rapport herstellen, Ausgangslage, Werte und Absichten erkunden. Ziel mit SPEZI- und/oder SMART-Kriterien formulieren, Auswirkungen intern und auf andere prüfen, Future Pace und Ergebnis schriftlich festhalten. Präsentation nennt außerdem eine 72-Stunden-Regel.',NULL,'','Die Folie schreibt SMART ausgeschrieben teilweise fehlerhaft; die Begriffe wurden hier nicht als Quelle korrigiert/validiert.','https://www.nlphamburg.de','Ziele,SMART,SPEZI','privat'),
(@format_owner_id,'Meta-Modell Sprache – Glaubenssätze entdecken','Sprache und Glaubenssätze','Einschränkende Aussagen und Sprachmuster erkennen.','Verallgemeinerungen, Verzerrungen und Auslassungen mit Fragen untersuchen.','Hinderliche Sätze sammeln. Bei Verallgemeinerungen nach Gegenbeispielen fragen; bei „wenn-dann“ nach Ausnahmen; bei verlorenen Urhebern nachfragen, wer das sagt. Nominalisierungen, Vorannahmen und Gedankenlesen explorieren; bei Auslassungen nach fehlenden Informationen fragen.',NULL,'','Fragen offen und wertschätzend stellen; keine Konfrontation oder Deutung aufzwingen.','https://www.nlphamburg.de','Sprache,Glaubenssätze','privat'),
(@format_owner_id,'Blockade/Schmerzen abfließen lassen – Ressourcen abtanken','Ressourcen','Die Präsentation beschreibt eine Ressourcenübung und nennt auch Schmerzen/Blockaden.','Bedarf an Ressourcen benennen und eine imaginative Übung dazu durchführen.','Benötigte Ressourcen besprechen. Nach Erlaubnis eine Übung mit geöffneten Handflächen anleiten: Belastendes imaginativ in Schalen abgeben, diese leeren; anschließend gewünschte Ressourcen imaginativ aufnehmen. Atem und Körperwahrnehmung einbeziehen und behutsam ausleiten.',NULL,'','Ungeprüfter Präsentationsinhalt mit Schmerzbezug. Keine Behandlung oder Schmerzlinderung versprechen; an medizinische Fachpersonen verweisen. Nur freiwillig und jederzeit abbrechbar.','https://www.nlphamburg.de','Ressourcen,Schmerz','privat'),
(@format_owner_id,'VAKOG – Submodalitäten','Wahrnehmung','Beispiele zur Beschreibung innerer Sinneswahrnehmungen.','Wahrnehmungsqualitäten strukturiert erkunden.','Beispiele aus der Präsentation: visuell (Helligkeit, Farbe, Größe, Entfernung, Bewegung, Schärfe), auditiv (Tempo, Lautstärke, Richtung, Klang) und kinästhetisch (Temperatur, Druck, Spannung, Bewegung); außerdem Geruch und Geschmack. Eigenschaften nur erkunden, soweit passend.',NULL,'','Beispielliste aus der Präsentation, kein eigener Interventionsablauf.','https://www.nlphamburg.de','VAKOG,Submodalitäten','privat'),
(@format_owner_id,'State-Management','Ressourcen','Die Präsentation beschreibt den Einfluss innerer Repräsentation, Verhalten und Physiologie.','Einflussfaktoren auf den aktuellen Zustand reflektieren.','Aktuellen Zustand und gewünschte Veränderung benennen. Innere Vorstellung (VAKOG), Verhalten und physiologische Faktoren wie Haltung und Atmung betrachten und eine passende Veränderung erproben.',NULL,'','Nur als allgemeine Selbstreflexion; keine medizinische Wirkung ableiten.','','Zustand,Ressourcen','privat'),
(@format_owner_id,'Hypnose – Ressourcen aktivieren','Ressourcen','Die Präsentation nennt Persönlichkeitsstärkung und Ressourcenaktivierung als mögliche Themen.','Ressourcenorientierte Entspannung oder Vorstellungsübung planen.','In der Präsentation wird Hypnose als Themenbereich genannt, jedoch kein Ablauf beschrieben. Vor der Anwendung muss ein qualifizierter, transparenter Ablauf separat ausgearbeitet werden.',NULL,'','Kein hypnotischer Ablauf aus der Quelle vorhanden. Nur durch dafür qualifizierte Fachpersonen mit ausdrücklicher Einwilligung; die Präsentation nennt auch Süchte, Schlaf, Schmerzen und psychische Themen ohne Beleg für Wirksamkeit.','https://www.nlphamburg.de','Hypnose,Ressourcen','privat');
