-- Coaching Tool: NLP-Formate aus „NLP Formate.pptx“
-- Importiert als private Einträge für den ersten aktiven Coach.
-- Vor Ausführung prüfen: Migration 006 (coaching_formate) muss installiert sein.
-- Bei mehreren Coaches @format_owner_id manuell auf die gewünschte benutzer.id setzen.
-- Die Zusammenfassungen geben den Folieninhalt wieder und sind keine unabhängige fachliche Prüfung.
-- Die Datei führt nur INSERT aus; sie sollte pro Datenbank nur einmal importiert werden.

SET @format_owner_id := (SELECT id FROM benutzer WHERE rolle = 'coach' AND aktiv = 1 ORDER BY id LIMIT 1);

